// Builds MIGRATION-SQL.md: every database file, in full, in run order.
//
//   node ops/migration/build-sql-bundle.mjs
//
// Run it again after adding a migration so the bundle never falls behind
// sql/. The order is the one tests/db/run.mjs proves on every test run:
// sql/*.sql sorted by name, with tests/db/prod-drift-after-17.sql right
// after 17, then ops/migration/after-restore.sql and count-rows.sql.
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
const rel = p => path.relative(root, p).split(path.sep).join('/');
const sqlDir = path.join(root, 'sql');
const RUN_ALONE = new Set(['15a-display-roles.sql', '29a-enum-values.sql', '37a-payment-enum.sql']);

const files = [];
for (const f of fs.readdirSync(sqlDir).filter(f => f.endsWith('.sql')).sort()) {
  files.push(path.join(sqlDir, f));
  if (f.startsWith('17-')) files.push(path.join(root, 'tests/db/prod-drift-after-17.sql'));
}

const fence = '`'.repeat(4);
const out = [];
out.push('# TPN OS: every SQL file, in run order');
out.push('');
out.push('Generated by `node ops/migration/build-sql-bundle.mjs` from the files in this repo. Do not edit by hand: change the file in `sql/` and run the script again. How and when to use these is in [MIGRATION.md](MIGRATION.md).');
out.push('');
out.push('- **Path A (project transfer) and Path B (dump and restore) do not run any of this** except `after-restore.sql` (Path B) and `count-rows.sql`. The dump already carries the whole database as it is on production.');
out.push('- **Path C (empty rebuild)** runs files 1 to ' + files.length + ' in this order, each one on its own in the Supabase SQL Editor (one Run per file), then `after-restore.sql`.');
out.push('- The three files marked **RUN ALONE** add enum values. Run each one by itself and wait for it to finish before the next file, because Postgres cannot use a new enum value in the same transaction that adds it.');
out.push('- `prod-drift-after-17.sql` adds two things production had before migrations were tracked. Run it straight after `17-hardening.sql`.');
out.push('- Run each file once, on an empty project. The early files (01 to 14) were not written to be run twice. The md5 after each name lets you check that you copied the whole file.');
out.push('- This file is large. If GitHub will not show it, open it with the **Raw** button, or read the same files straight from `sql/`.');
out.push('');
out.push('## Run order');
out.push('');
files.forEach((f, i) => {
  const name = path.basename(f);
  out.push(`${i + 1}. [\`${rel(f)}\`](#${i + 1})${RUN_ALONE.has(name) ? ' **RUN ALONE**' : ''}`);
});
out.push(`${files.length + 1}. [\`ops/migration/after-restore.sql\`](#after-restore)`);
out.push(`${files.length + 2}. [\`ops/migration/count-rows.sql\`](#count-rows)`);
out.push('');

const block = (anchor, title, file) => {
  const body = fs.readFileSync(file, 'utf8').replace(/\s+$/, '');
  const md5 = crypto.createHash('md5').update(fs.readFileSync(file)).digest('hex');
  out.push(`<a id="${anchor}"></a>`);
  out.push('');
  out.push(`## ${title}`);
  out.push('');
  out.push(`\`${rel(file)}\` · ${body.split('\n').length} lines · md5 \`${md5}\``);
  out.push('');
  out.push(fence + 'sql');
  out.push(body);
  out.push(fence);
  out.push('');
};

files.forEach((f, i) => {
  const name = path.basename(f);
  block(String(i + 1), `${i + 1}. ${name}${RUN_ALONE.has(name) ? ' (RUN ALONE)' : ''}`, f);
});
block('after-restore', 'after-restore.sql', path.join(root, 'ops/migration/after-restore.sql'));
block('count-rows', 'count-rows.sql', path.join(root, 'ops/migration/count-rows.sql'));

fs.writeFileSync(path.join(root, 'MIGRATION-SQL.md'), out.join('\n') + '\n');
console.log(`MIGRATION-SQL.md: ${files.length} migration files + 2 helpers`);
